<?php include "auth.php";include "conection.php";$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['nama_lengkap']??'');$u=trim($_POST['username']??'');$p=$_POST['password']??'';$role=trim($_POST['role']??'Admin');if($n===''||$u===''||$p==='')$error='Semua field wajib diisi.';else{$h=password_hash($p,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(nama_lengkap,username,password,role) VALUES(?,?,?,?)");$s->bind_param("ssss",$n,$u,$h,$role);if($s->execute()){header("Location:admin.php");exit;}$error=$s->error;}}?>
